'use client';

// WorkflowPage — one page per workflow, three modes:
//   Overview  → "see what they built" (the process; live for all 15 blueprints)
//   Run       → "do the repeatable work" (the interactive loop; live only where a
//               deterministic engine exists — today FAPI. Otherwise a stub + a
//               link to open the blueprint in the builder.)
//   Results   → "see the results" (the manager worksheet; link when one exists)
//
// The engine — not the page — is the gate: Overview is free for everything; Run
// and Results light up per-workflow as deterministic cores are built. Step 1
// ships Overview live with Run/Results stubbed but honestly wired where possible.

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { useSetAtom } from 'jotai';
import { useTheme } from 'next-themes';
import { ArrowLeft, ArrowRight, GitFork } from 'lucide-react';
import { getPortfolioWorkflowDef } from '@/shared/workflow-engine/templates/portfolio/portfolio-workflows';
import { getWorkflowConfig } from '@/shared/workflow-engine/runtime/workflow-runs';
import { builderFocusTargetAtom } from '@/shared/workflow-engine/state/workflow-store';
import { getAgent } from '@/lib/agents';
import { getPage } from '@/shared/stores/resource-registry';
import { WorkflowRunFlow } from '@/features/assistant/workspace/workflow-run-flow';
import { NEU } from '@/components/neumorphic-sidebar';
import { WorkflowOverview } from '@/features/workflows-hub/workflow-overview';

type Tab = 'overview' | 'run' | 'results';

function StubCard({ title, body, action }: { title: string; body: string; action?: { label: string; icon: React.ReactNode; onClick: () => void } }) {
  return (
    <div style={{ maxWidth: 560, background: NEU.surface, borderRadius: 16, boxShadow: NEU.shadowSm, padding: '22px 24px' }}>
      <div style={{ fontSize: 15, fontWeight: 700, color: NEU.text }}>{title}</div>
      <div style={{ fontSize: 13, lineHeight: 1.6, color: NEU.muted, margin: '8px 0 0' }}>{body}</div>
      {action && (
        <button
          onClick={action.onClick}
          style={{ marginTop: 18, display: 'inline-flex', alignItems: 'center', gap: 8, border: 'none', cursor: 'pointer', background: NEU.bg, boxShadow: NEU.shadowSm, color: NEU.accent, fontSize: 13, fontWeight: 650, borderRadius: 11, padding: '10px 16px' }}
        >
          {action.icon}{action.label}<ArrowRight size={15} />
        </button>
      )}
    </div>
  );
}

export function WorkflowPage({ workflowId }: { workflowId: string }) {
  const router = useRouter();
  const setBuilderFocus = useSetAtom(builderFocusTargetAtom);
  const { resolvedTheme } = useTheme();
  const [tab, setTab] = useState<Tab>('overview');
  const def = getPortfolioWorkflowDef(workflowId);

  if (!def) {
    return (
      <div style={{ display: 'grid', placeItems: 'center', height: '100%', color: NEU.muted, fontSize: 14 }}>
        Unknown workflow “{workflowId}”.
        <button onClick={() => router.push('/workflows-hub')} style={{ marginLeft: 8, color: NEU.accent, background: 'none', border: 'none', cursor: 'pointer', fontWeight: 600 }}>All workflows</button>
      </div>
    );
  }

  // A blueprint is runnable when a matching run-config exists (pf-fapi → fapi).
  const runnable = getWorkflowConfig(def.id.replace(/^pf-/, ''));
  const resultPage = runnable?.resultPage;
  const agent = runnable?.agentId ? getAgent(runnable.agentId) ?? undefined : undefined;
  const surface: 'dark' | 'light' = resolvedTheme === 'dark' ? 'dark' : 'light';

  const TABS: { id: Tab; label: string }[] = [
    { id: 'overview', label: 'Overview' },
    { id: 'run', label: 'Run' },
    { id: 'results', label: 'Results' },
  ];

  return (
    <div style={{ height: '100%', overflowY: 'auto', fontFamily: "'Inter', ui-sans-serif, system-ui, sans-serif", background: NEU.bg }}>
      <div style={{ maxWidth: 820, margin: '0 auto', padding: '28px 28px 56px' }}>
        <button
          onClick={() => router.push('/workflows-hub')}
          style={{ display: 'inline-flex', alignItems: 'center', gap: 6, background: 'none', border: 'none', cursor: 'pointer', color: NEU.muted, fontSize: 13, fontWeight: 550, padding: 0, marginBottom: 16 }}
        >
          <ArrowLeft size={15} /> All workflows
        </button>

        <h1 style={{ margin: 0, fontSize: 25, fontWeight: 750, color: NEU.text, letterSpacing: '-0.02em' }}>
          {def.name.replace(/^Platform Services · /, '')}
        </h1>

        {/* Segmented mode switch */}
        <div style={{ display: 'inline-flex', gap: 3, padding: 4, borderRadius: 999, background: 'var(--sx-nav-track)', boxShadow: NEU.shadowIn, marginTop: 18 }}>
          {TABS.map((t) => {
            const active = tab === t.id;
            return (
              <button
                key={t.id}
                onClick={() => setTab(t.id)}
                style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '7px 18px', borderRadius: 999, border: 'none', cursor: 'pointer', fontSize: 13, fontWeight: 600, color: active ? NEU.accent : NEU.muted, background: active ? 'var(--sx-nav-pill)' : 'transparent', boxShadow: active ? NEU.shadowSm : 'none' }}
              >
                {t.label}
                {t.id !== 'overview' && !(t.id === 'run' ? runnable : resultPage) && (
                  <span style={{ fontSize: 9, fontWeight: 700, color: NEU.faint, textTransform: 'uppercase' }}>soon</span>
                )}
              </button>
            );
          })}
        </div>

        <div style={{ marginTop: 24 }}>
          {tab === 'overview' && <WorkflowOverview def={def} />}

          {tab === 'run' && (
            runnable ? (
              // The repeatable work runs RIGHT HERE — upload → classify → resolve
              // checkpoints → approve — no detour to the builder. On finish it flips
              // to Results (the worksheet), which reads the same run.
              <div style={{ background: NEU.surface, borderRadius: 18, boxShadow: NEU.shadowSm, padding: '16px 16px 12px' }}>
                <WorkflowRunFlow
                  config={runnable}
                  agent={agent}
                  surface={surface}
                  onComplete={() => setTab('results')}
                  onOpenPage={(pk) => { if (resultPage && pk === resultPage) setTab('results'); else router.push(`/${pk}`); }}
                  onOpenBuilder={(blockId) => { setBuilderFocus({ workflowId: def.id, blockId }); router.push('/builder'); }}
                />
              </div>
            ) : (
              <StubCard
                title="Run — engine not built yet"
                body="This workflow is a structural blueprint: it maps the standardized process, but its calculation engine hasn't been built. Once it is, you'll run it right here and the result lands in Results — no builder needed to run. (Authors can open the graph below to edit it.)"
                action={{ label: 'Open the graph in the builder', icon: <GitFork size={15} />, onClick: () => { setBuilderFocus({ workflowId: def.id, blockId: '' }); router.push('/builder'); } }}
              />
            )
          )}

          {tab === 'results' && (() => {
            const ResultComp = resultPage ? getPage(resultPage)?.Component : null;
            if (ResultComp) {
              // The manager worksheet — the deliverable — embedded in-page. It reads
              // the same shared run state, so it shows the run you just did.
              return (
                <div style={{ borderRadius: 16, overflow: 'hidden', boxShadow: NEU.shadowSm, background: 'var(--sx-card)' }}>
                  <ResultComp />
                </div>
              );
            }
            return (
              <StubCard
                title="Results appear here after a run"
                body="Once this workflow runs and is approved, its manager-reviewable worksheet — the deliverable — shows up right here (and in the Worksheets library)."
              />
            );
          })()}
        </div>
      </div>
    </div>
  );
}
