'use client';

// Standalone workflow page route — /w/<workflowId> (e.g. /w/pf-t1134). Renders
// the WorkflowPage (Overview / Run / Results) for a Sinaxe portfolio workflow.

import { useParams } from 'next/navigation';
import { WorkflowPage } from '@/features/workflows-hub/workflow-page';

export default function WorkflowRoute() {
  const params = useParams();
  const workflowId = String(params?.workflowId ?? '');
  return <WorkflowPage workflowId={workflowId} />;
}
